    template <typename Self = DbRowID>
    static constexpr std::span<const Entry> entries() {
        static_assert(detail::HasGamevalTable<Self>,
                      "DbRowID lookups need #include <titan/generated/gamevals/db_row_id_table.h>");
        return detail::GamevalTable<Self>::entries();
    }
    template <typename Self = DbRowID>
    static const Entry* byId(int32_t id) { return findById(entries<Self>(), id); }
